/* Palette: #2b2d42 (dark), #8d99ae (gray), #edf2f4 (light), #ef233c (red), #d90429 (dark red) */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #2b2d42;
  color: #edf2f4;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #edf2f4;
  color: #2b2d42;
  border-radius: 16px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #2b2d42;
}

.pet-container {
  width: 120px;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pet {
  position: relative;
  width: 80px;
  height: 80px;
  background: #8d99ae;
  border-radius: 12px;
  box-shadow: 0 0 0 4px #2b2d42;
  transition: transform 0.2s;
}

.pet-body {
  position: absolute;
  inset: 12px;
  background: #edf2f4;
  border-radius: 8px;
}

.pet-eye {
  position: absolute;
  width: 12px;
  height: 12px;
  background: #2b2d42;
  border-radius: 50%;
  top: 28px;
}

.pet-eye.left {
  left: 18px;
}

.pet-eye.right {
  right: 18px;
}

.pet-mouth {
  position: absolute;
  width: 20px;
  height: 6px;
  background: #2b2d42;
  border-radius: 0 0 10px 10px;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 12px;
}

.stat-label {
  width: 80px;
  font-weight: 600;
  font-size: 0.95rem;
  color: #2b2d42;
}

.bar {
  flex: 1;
  height: 16px;
  background: #8d99ae;
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: #ef233c;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.mood {
  font-size: 1.1rem;
  font-weight: 600;
  color: #d90429;
  text-align: center;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: #2b2d42;
  color: #edf2f4;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: #3d3f5a;
}

button:focus-visible {
  outline: 3px solid #ef233c;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #1a1b2e;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .stat-label {
    width: 70px;
    font-size: 0.85rem;
  }
  button {
    padding: 10px 16px;
    font-size: 0.9rem;
  }
}

const state = {
  hunger: 70,
  happiness: 70,
  energy: 70
};

const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood');
const pet = document.getElementById('pet');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  let mood = 'Happy';
  if (state.hunger < 30) mood = 'Hungry';
  else if (state.happiness < 30) mood = 'Sad';
  else if (state.energy < 30) mood = 'Tired';
  else if (state.hunger > 80 && state.happiness > 80 && state.energy > 80) mood = 'Ecstatic';
  moodText.textContent = 'Mood: ' + mood;

  pet.style.transform = 'scale(1)';
  pet.offsetHeight;
  pet.style.transform = 'scale(1.05)';
  setTimeout(() => { pet.style.transform = 'scale(1)'; }, 200);
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
